import 'dart:convert';import 'package:flutter/material.dart';import 'package:intl/intl.dart';import 'package:sqflite/sqflite.dart';import '../../../core/data/local_database.dart';import '../../../core/models/reading.dart';import '../../../core/theme/app_theme.dart';import '../../../shared/widgets/app_components.dart';
class LunarScreen extends StatefulWidget{const LunarScreen({super.key});@override State<LunarScreen> createState()=>_LunarScreenState();}
class _LunarScreenState extends State<LunarScreen>{List<LunarEvent> events=[];String state='Lunar events appear only when a verified, precomputed dataset is installed.';@override void initState(){super.initState();_load();}
Future<void> _load()async{final db=await LocalDatabase.instance.database;final rows=await db.query('lunar_events');final found=<LunarEvent>[];for(final row in rows){try{final d=jsonDecode(row['payload'] as String) as Map<String,dynamic>;found.add(LunarEvent.fromJson(d));}catch(_){}}if(mounted)setState(()=>events=found..sort((a,b)=>DateTime.parse(a.timestampUtc).compareTo(DateTime.parse(b.timestampUtc))));}
@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Moon calendar')),body:events.isEmpty?ListView(padding:const EdgeInsets.all(22),children:[const PageHeader('Lunar calendar',subtitle:'New moon · First quarter · Full moon · Last quarter'),InfoCard(state),const SizedBox(height:12),const Text('AstroDaily does not estimate moon phases with a rough client-side formula. Events require source name, UTC timestamp, source timezone, dataset version, verification date and source URL.'),const DisclaimerCard()]):ListView(padding:const EdgeInsets.all(18),children:[const PageHeader('Moon calendar',subtitle:'Event times are shown in your device timezone.'),for(final e in events)Card(child:ListTile(leading:const Icon(Icons.nightlight_round,color:AppTheme.primary),title:Text(e.phase),subtitle:Text(DateFormat.yMMMd().add_jm().format(DateTime.parse(e.timestampUtc).toLocal())),onTap:()=>showDialog(context:context,builder:(_)=>AlertDialog(title:Text(e.phase),content:Text(e.note+'\n\nSource: '+e.sourceName+'\nSource timezone: '+e.sourceTimezone+'\nDataset: '+e.datasetVersion+'\nVerified: '+e.verifiedAt+'\n'+e.sourceUrl))))),const DisclaimerCard()]);}
}
